steps.snippet:
idx = device.find(text="Create new contact", clickable=True)
if idx is None:
    idx = device.find(contains="Create new contact", clickable=True)
if idx is None:
    raise RuntimeError("Could not find 'Create new contact' entry to open the contact editor")
device.click(index=idx)

for _ in range(10):
    elements = device.elements()
    if any(e.get('editable') and 'EditText' in e.get('class', '') and e.get('hint') and ('phone' in e['hint'].lower() or 'mobile' in e['hint'].lower()) for e in elements):
        break
    device.scroll(direction="down")
else:
    raise RuntimeError("Phone number field not found")

collapse = device.find(description="Collapse", clickable=True)
if collapse is not None:
    device.click(collapse)
elif device.find(description="Expand", clickable=True) is None:
    raise RuntimeError("No panel toggle button ('Collapse'/'Expand') found on screen")
# else: panel is already collapsed -> nothing to do
